 const sourceOK=r.sourcePins.every(sourceReady),stageOK=r.standalone?ss.length===0&&p?.isStandaloneInchoate===true:ss.length===3&&new Set(ss.map(c=>c.stageType)).size===3&&ss.every(c=>codes[c.stageType]&&c.stageStatus===(r.allowed.includes(codes[c.stageType])?'punishable':'not-criminalized')&&c.individualLegalAudit15?.scope?.status==='APPROVED'&&c.individualLegalAudit15.scope.caseSpecificLiabilityApproved===false);
 if(!sourceOK||!stageOK||!p||p.title!==r.title||p.statute!==r.statute||p.shortRef!==r.shortRef||p.lawMode!=='full'||p.lawCompletenessVerified!==true||p.lawCompletenessSourceURL!==r.sourceURL||n(p.law)!==n(r.ownText)||p.legalAudit15?.checkpoints?.inchoate){report.held.push({id:r.id,sourceOK,stageOK});continue;}
 const yes=[...r.allowed].map(k=>names[k]),no=Object.entries(names).filter(([k])=>!r.allowed.includes(k)).map(([,v])=>v);
 const summary=r.standalone?'Självständig förberedelsebestämmelse.':yes.length?'Särskilt lagstöd för '+yes.join(', ')+'.'+(no.length?' Inte särskilt uppräknat: '+no.join(', ')+'.':''):'Inget särskilt lagstöd för försök, förberedelse eller stämpling i den kontrollerade bestämmelsen.';
 const finding=p.title+' ('+p.shortRef+'): '+summary+' '+r.note+' Kontrollen gäller den aktuella lagtextens uppräkning; villkoren i 23 kap., praxis och gärningsdatum måste prövas separat.';
 p.baseInchoateReview15={checked:report.checked,summary,note:r.note,source:r.authorizer,sourceURL:r.sourceURL,allowed:r.allowed,standalone:r.standalone,caseSpecificLiabilityApproved:false};
 p.legalAudit15={...p.legalAudit15,fullLegalReviewApproved:false,checkpoints:{...p.legalAudit15?.checkpoints,inchoate:{status:'APPROVED',checked:report.checked,sourceURL:r.sourceURL,sourceRefs:[p.shortRef,r.authorizer,'BrB 23:1–3'],finding,scope:'current-statutory-inchoate-listing-and-express-branch-limits-only',caseSpecificLiabilityApproved:false,historicLawApproved:false,jurisprudenceApproved:false,caseSpecificCustodyApproved:false,penaltyRangeApproved:false,fullChapter23CaseAssessmentApproved:false}}};
 // Legacy later enrichers must not restore automatic prosecution conclusions
