 for(const c of ss)if(window.BK_STAGE_GRADE_CORRECTIONS15?.superseded?.some(x=>x.id===c.id)){c.custody='unknown';c.prosecution='unknown';c.prosecutionLabel='Åtalsvillkor måste kontrolleras';c.prosecutionRule='Ej individuellt kontrollerat';c.prosecutionChecked=null;c.prosecutionSource=c.stageSource;c.prosecutionDetails=['Förstadiets åtalsvillkor måste kontrolleras separat. Grundbrottets huvudregel räcker inte för ett konkret åtalsbeslut.'];c.penaltyRange=null;c.penaltyRangeVerified=false;}
 report.completed++;const family=r.statute?.split(':')[0]||r.shortRef.split(' ')[0];report.byFamily[family]=(report.byFamily[family]||0)+1;
