(()=>{'use strict';const D=window.BK_DATA,W=window.BK_STATUTES;if(!D?.crimes||!W)return;
const data={"checked":"2026-10-21","rules":[{"id":"stadium-08-forsok-v05-grov-forgoring","parentId":"v05-grov-forgoring","title":"Försök till grov förgöring","statute":"BrB:13:8","authorizer":"BrB:13:12","parentRange":{"min":0.5,"max":6,"fines":false,"life":false},"range":{"min":0,"max":6,"fines":true,"life":false},"label":"Böter – fängelse högst 6 år"},{"id":"stadium-08-forsok-v05-grovt-hindrande-av-urkunds-bevisfunktion","parentId":"v05-grovt-hindrande-av-urkunds-bevisfunktion","title":"Försök till grovt hindrande av urkunds bevisfunktion","statute":"BrB:14:4","authorizer":"BrB:14:13","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"},{"id":"stadium-08-forsok-v05-grov-bevisforvanskning","parentId":"v05-grov-bevisforvanskning","title":"Försök till grov bevisförvanskning","statute":"BrB:15:8","authorizer":"BrB:15:15","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"},{"id":"stadium-08-forsok-v15-grov-signaturforfalskning","parentId":"v15-grov-signaturforfalskning","title":"Försök till grov signaturförfalskning","statute":"BrB:14:5","authorizer":"BrB:14:13","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"},{"id":"stadium-08-forsok-v15-grov-olovlig-befattning-med-falska-pengar","parentId":"v15-grov-olovlig-befattning-med-falska-pengar","title":"Försök till grov olovlig befattning med falska pengar","statute":"BrB:14:7","authorizer":"BrB:14:13","parentRange":{"min":0.5,"max":6,"fines":false,"life":false},"range":{"min":0,"max":6,"fines":true,"life":false},"label":"Böter – fängelse högst 6 år"},{"id":"stadium-08-forsok-v15-grov-markesforfalskning","parentId":"v15-grov-markesforfalskning","title":"Försök till grov märkesförfalskning","statute":"BrB:14:8","authorizer":"BrB:14:13","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"},{"id":"stadium-08-forsok-v15-cover-grov-olovlig-underrattelseverksamhet-mot-frammande-makt","parentId":"v15-cover-grov-olovlig-underrattelseverksamhet-mot-frammande-makt","title":"Försök till grov olovlig underrättelseverksamhet mot främmande makt","statute":"BrB:19:10a","authorizer":"BrB:19:14","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"},{"id":"stadium-08-forsok-v15-cover-grov-olovlig-underrattelseverksamhet-mot-person","parentId":"v15-cover-grov-olovlig-underrattelseverksamhet-mot-person","title":"Försök till grov olovlig underrättelseverksamhet mot person","statute":"BrB:19:10b","authorizer":"BrB:19:14","parentRange":{"min":0.5,"max":4,"fines":false,"life":false},"range":{"min":0,"max":4,"fines":true,"life":false},"label":"Böter – fängelse högst 4 år"}],"pins":{"BrB:23:1":{"text":"1 §\nDen som har påbörjat utförandet av ett visst brott, utan att brottet fullbordats, döms för försök till brottet om sådant ansvar är särskilt föreskrivet och det har funnits fara för att handlingen skulle leda till att brottet fullbordas eller sådan fara varit utesluten endast på grund av tillfälliga omständigheter.\nOavsett vad som föreskrivs om fara i första stycket, ska det dömas till ansvar för försök till brott om fara för brottets fullbordan varit utesluten till följd av en myndighets åtgärd för att bekämpa brott. Detta gäller dock inte om gärningen med hänsyn till omständigheterna är uppenbart mindre allvarlig.\nStraffet för försök till brott bestäms högst till vad som gäller för fullbordat brott och får inte bestämmas till böter, om lägsta straff för det fullbordade brottet är fängelse i två år eller mer.\nLag (2026:93).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:13:8":{"text":"8 §\nFramkallar någon allmän fara för djur eller växter medelst gift eller genom att överföra eller sprida elakartad sjukdom eller genom att sprida skadedjur eller ogräs eller på annat dylikt sätt, dömes för förgöring till böter eller fängelse i högst två år.\nÄr brottet grovt, skall dömas till fängelse, lägst sex månader och högst sex år. Vid bedömande huruvida brottet är grovt skall särskilt beaktas, om det skett med uppsåt att skada eller om egendom av betydande värde utsatts för fara.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:13:12":{"text":"12 §\nFör försök, förberedelse eller stämpling till mordbrand, grov mordbrand, allmänfarlig ödeläggelse, grov allmänfarlig ödeläggelse, sabotage, grovt sabotage, kapning, sjö- eller luftfartssabotage, flygplatssabotage, sabotage mot blåljusverksamhet, grovt sabotage mot blåljusverksamhet, spridande av gift eller smitta eller till förgöring och för underlåtenhet att avslöja eller förhindra sådant brott döms det till ansvar enligt 23 kap. Lag (2023:257).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:14:4":{"text":"4 §\nDen som utan att vid tillfället ha rätt till det förstör, gör obrukbar eller döljer en urkund döms, om åtgärden innebär fara i bevishänseende och brottet inte är att anse som bokföringsbrott, för hindrande av urkunds bevisfunktion till fängelse i högst två år.\nÄr brottet ringa, döms till böter eller fängelse i högst sex månader.\nÄr brottet grovt, döms till fängelse i lägst sex månader och högst fyra år. Lag (2013:425).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:14:13":{"text":"13 §\nFör försök eller förberedelse till urkundsförfalskning, grov urkundsförfalskning, hindrande av urkunds bevisfunktion, signaturförfalskning, penningförfalskning, märkesförfalskning, förfalskning av fast märke eller brukande av vad som förfalskats och för underlåtenhet att avslöja eller förhindra penningförfalskning döms det till ansvar enligt 23 kap. Detsamma gäller för försök till olovlig befattning med falska pengar som består i försök till anskaffande eller mottagande av det förfalskade.\nSkulle brottet, om det fullbordats, ha varit att anse som ringa, ska gärningen dock inte medföra ansvar. Lag (2016:508).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:15:8":{"text":"8 §\nFörvanskar eller undanröjer någon bevis med uppsåt att oskyldig må bliva fälld till ansvar eller åberopar någon med sådant uppsåt falskt bevis, dömes för bevisförvanskning till fängelse i högst två år eller, om brottet är ringa, till böter eller fängelse i högst sex månader.\n\nÄr brottet grovt, dömes till fängelse, lägst sex månader och högst fyra år.","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:15:15":{"text":"15 §\nFör förberedelse eller stämpling till mened som inte är mindre allvarlig eller grov mened och för försök till bevisförvanskning som inte är ringa döms det till ansvar enligt 23 kap. Lag (2026:1318).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:14:5":{"text":"5 §\nDen som olovligen anbringar eller annars förfalskar någon annans namnteckning eller signatur på ett alster av konst eller brukskonst eller på annat sådant verk och därigenom ger sken av att den personen angett sig vara upphovsman till verket döms för signaturförfalskning till fängelse i högst två år.\nÄr brottet ringa, döms till böter eller fängelse i högst sex månader.\nÄr brottet grovt, döms till fängelse i lägst sex månader och högst fyra år. Lag (2013:425).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:14:7":{"text":"7 §\nDen som anskaffar, lämnar, tar emot, förvarar, transporterar eller tar annan liknande befattning med falsk sedel eller falskt mynt som avses i 6 §, med uppsåt att det förfalskade ska prånglas ut, döms för olovlig befattning med falska pengar till fängelse i högst två år.\nÄr brottet ringa, döms till böter eller fängelse i högst sex månader.\nÄr brottet grovt, döms till fängelse i lägst sex månader och högst sex år. Lag (2016:348).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:14:8":{"text":"8 §\nDen som eftergör gällande frimärke, beläggningsstämpel eller annat offentligt eller för allmänheten avsett svenskt eller utländskt värdemärke eller offentlig svensk eller utländsk kontrollmärkning på mått, vikt, vara, handling eller annat, eller anbringar falskt sådant märke eller obehörigen anbringar äkta märke eller annars förfalskar sådant märke eller det märkta, döms, om åtgärden innebär fara i bevishänseende, för märkesförfalskning till fängelse i högst två år.\nÄr brottet ringa, döms till böter eller fängelse i högst sex månader.\n\nÄr brottet grovt, döms till fängelse i lägst sex månader och högst fyra år. Lag (2013:425).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:19:10a":{"text":"10 a §\nDen som, för att gå en främmande makt eller motsvarande tillhanda, här i landet antingen bedriver verksamhet vars syfte är anskaffande av uppgifter om förhållanden vars uppenbarande för den främmande makten eller motsvarande kan medföra men för annan främmande makts säkerhet eller medverkar till sådan verksamhet mer än tillfälligt, döms för olovlig underrättelseverksamhet mot främmande makt till böter eller fängelse i högst ett år.\nOm brottet är grovt döms till fängelse i lägst sex månader och högst fyra år.\nLag (2022:1519).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:19:14":{"text":"14 §\n\nFör försök, förberedelse eller stämpling till högförräderi, trolöshet vid förhandling med främmande makt, spioneri, grovt spioneri, utlandsspioneri, grovt utlandsspioneri, grov obehörig befattning med hemlig uppgift, olovlig underrättelseverksamhet mot främmande makt eller olovlig underrättelseverksamhet mot person döms det till ansvar enligt 23 kap. Detsamma gäller för försök eller förberedelse till obehörig befattning med hemlig uppgift.\n\nSom stämpling till högförräderi ska även anses att träda i förbindelse med främmande makt för att förbereda, möjliggöra eller underlätta att sådant brott kan begås.\n\nDen som underlåter att avslöja eller förhindra högförräderi, trolöshet vid förhandling med främmande makt, spioneri, grovt spioneri, utlandsspioneri, grovt utlandsspioneri eller grov obehörig befattning med hemlig uppgift döms till ansvar enligt 23 kap. Detsamma gäller även om han eller hon inte insett men borde ha insett att brottet var förestående eller pågick. Lag (2022:1519).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"},"BrB:19:10b":{"text":"10 b §\nDen som, med uppsåt att gå en främmande makt eller motsvarande tillhanda, här i landet hemligen eller med användande av svikliga eller otillbörliga medel antingen bedriver verksamhet vars syfte är anskaffande av uppgifter om någon annans personliga förhållanden eller medverkar till sådan verksamhet mer än tillfälligt, döms för olovlig underrättelseverksamhet mot person till fängelse i högst ett år.\nOm brottet är grovt döms till fängelse i lägst sex månader och högst fyra år.\nLag (2022:1519).","url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/brottsbalk-1962700_sfs-1962-700/"}}};
const norm=s=>String(s||'').normalize('NFC').replace(/\s+/g,' ').trim();
const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Stockholm'});
const sourceReady=key=>{const p=W[key],pin=data.pins[key];return p?.complete===true&&p.machine===false
 &&p.completeTextProvenance==='manual-crosscheck-current-SFS-paragraph-only'
 &&/^\d{4}-\d{2}-\d{2}$/.test(p.checked||'')&&p.checked<=today
 &&p.url===pin.url&&norm(p.text)===norm(pin.text);};
const report={planned:8,reviewed:0,duplicates:0,held:[],checked:data.checked,fullLegalApprovals:0,coercionApprovals:0};
for(const r of data.rules){const p=D.crimes.find(c=>c.id===r.parentId&&!c.stageType),c=D.crimes.find(c=>c.id===r.id);
 const ready=Boolean(c&&p&&c.title===r.title&&p.statute===r.statute&&c.stageParentId===p.id&&c.stageType==='forsok'
 &&c.stageStatus==='punishable'
 &&c.individualLegalAudit15?.scope?.finding==='CURRENT_BRB_SAME_SECTION_GRADE_COVERED_BY_NAMED_STAGE'
 &&p.lawMode==='full'&&p.lawCompletenessVerified===true&&p.penaltyRangeVerified===true&&!p.conditionalPenalty
 &&JSON.stringify(p.penaltyRange)===JSON.stringify(r.parentRange)
 &&norm(p.law)===norm(data.pins[r.statute].text)
 &&[r.statute,r.authorizer,'BrB:23:1'].every(sourceReady));
 if(!ready){report.held.push(r.id);continue;}
 const wasReviewed=Boolean(c.stageAttemptPenaltyReview15);
 if(wasReviewed&&JSON.stringify(c.penaltyRange)===JSON.stringify(r.range)&&c.penaltyRangeVerified===true){report.duplicates++;continue;}
 if(c.penaltyRange!==null||c.penaltyRangeVerified===true){report.held.push(r.id);continue;}
 const note='Separat källkontroll '+data.checked+': '+r.label+'. BrB 23:1 medger högst fullbordansbrottets straff och utesluter inte böter när fullbordansbrottets minimistraff är sex månader. Detta är den ordinära lagstadgade försöksskalan; allmänna straffskalemodifieringar, gärningsdag, ansvar och konkret påföljd prövas särskilt. Åtals- och tvångsmedelsbedömning är fortsatt öppen.';
 c.penaltyRange={...r.range};c.penaltyRangeVerified=true;c.penalty=r.label;c.penaltyShort='B–F '+r.range.max+' år';
 c.stagePenaltyLower='Böter';c.stagePenaltyUpper=r.range.max+' år';c.penaltyNote=note;c.stageConsequenceNote15=note;
 c.penaltyChecked=data.checked;c.penaltyReviewScope='individual-current-attempt-statutory-range-only';
 c.stageAttemptPenaltyReview15={checked:data.checked,sourceURL:data.pins[r.statute].url,sourceRefs:[r.statute,r.authorizer,'BrB:23:1'],
  scope:'ordinary-current-statutory-attempt-range-only',range:{...r.range},parentRange:{...r.parentRange},
  historicApplicabilityApproved:false,caseSpecificSentenceApproved:false,caseSpecificLiabilityApproved:false,
  prosecutionApproved:false,coercionApproved:false,fullLegalReviewApproved:false,note};
 if(wasReviewed)report.duplicates++;else report.reviewed++;
}
window.BK_STAGE_ATTEMPT_PENALTY_REVIEW15=report;
})();

